SELECT programacionCultivos.codigosistema, programacionCultivos.codSemilla, programacionCultivos.fechasiembra, Format$(Date(),"ww",0,0) AS semanaActual, (Date()-[programacionCultivos].[fechasiembra]) AS [#dias], Format$(([fechasiembra]+25),"ww",0,0) AS semana1, Format$(([fechasiembra]+50),"ww",0,0) AS semana2, Format$(([fechasiembra]+75),"ww",0,0) AS semana3, infoSemilla.abonoPrimera, infoSemilla.abonoSegunda, infoSemilla.abonoTercera, programacionCultivos.numeroPlantasSembradas
FROM infoSemilla INNER JOIN programacionCultivos ON infoSemilla.[Id] = programacionCultivos.[codSemilla]
GROUP BY programacionCultivos.codigosistema, programacionCultivos.codSemilla, programacionCultivos.fechasiembra, Format$(Date(),"ww",0,0), (Date()-[programacionCultivos].[fechasiembra]), Format$(([fechasiembra]+25),"ww",0,0), Format$(([fechasiembra]+50),"ww",0,0), Format$(([fechasiembra]+75),"ww",0,0), infoSemilla.abonoPrimera, infoSemilla.abonoSegunda, infoSemilla.abonoTercera, programacionCultivos.numeroPlantasSembradas;

